  },
  situationMeta: { gap: spacing[2] },
  situationLabel: {
    fontFamily: 'Inter_600SemiBold',
    fontSize: typeScale.tiny.fontSize,
    color: colors.text.tertiary,
    letterSpacing: 1.2,
  },
